def min_total_road_length(T, test_cases):
    results = []
    for case in test_cases:
        N, A = case
        if N == 1:
            results.append(0)
            continue

        max_and = 0
        for i in range(N):
            for j in range(i+1, N):
                max_and = max(max_and, A[i] & A[j])

        if max_and == 0:
            results.append(-1)
        else:
            results.append(max_and * (N - 1))
    return results

